import * as THREE from "three";

/** Shared wave field: drives both the ocean mesh and the rider's motion. */
export function waveHeight(x, z, t) {
  return (
    0.42 * Math.sin(0.18 * x + t * 1.05) +
    0.34 * Math.sin(0.21 * z - t * 0.85 + 1.3) +
    0.2 * Math.sin(0.1 * (x + z) + t * 0.55) +
    0.12 * Math.sin(0.45 * x - 0.3 * z + t * 1.7)
  );
}

export function waveNormal(x, z, t) {
  const e = 0.35;
  const dx = waveHeight(x + e, z, t) - waveHeight(x - e, z, t);
  const dz = waveHeight(x, z + e, t) - waveHeight(x, z - e, t);
  return new THREE.Vector3(-dx / (2 * e), 1, -dz / (2 * e)).normalize();
}

export function createOcean() {
  const geo = new THREE.PlaneGeometry(140, 140, 88, 88);
  geo.rotateX(-Math.PI / 2);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x1593a8,
    roughness: 0.55,
    metalness: 0.05,
    flatShading: true,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.receiveShadow = true;
  const pos = geo.attributes.position;
  const base = pos.array.slice();

  function update(t) {
    for (let i = 0; i < pos.count; i++) {
      const x = base[i * 3];
      const z = base[i * 3 + 2];
      pos.setY(i, waveHeight(x, z, t));
    }
    pos.needsUpdate = true;
    geo.computeVertexNormals();
  }
  update(0);
  return { mesh, update };
}

/** A curling barrel wave standing behind the rider, built from an open cylinder. */
export function createBarrel() {
  const group = new THREE.Group();
  const geo = new THREE.CylinderGeometry(7.5, 7.5, 46, 32, 1, true, Math.PI * 0.08, Math.PI * 0.78);
  const mat = new THREE.MeshStandardMaterial({
    color: 0x1fb0b4,
    roughness: 0.35,
    metalness: 0.02,
    side: THREE.DoubleSide,
    transparent: true,
    opacity: 0.92,
  });
  const curl = new THREE.Mesh(geo, mat);
  // Lay the cylinder along X so the open arc curls over like a breaking crest.
  curl.rotation.z = Math.PI / 2;
  curl.rotation.y = Math.PI / 2;
  group.add(curl);

  // Foamy lip along the top edge of the curl.
  const foamMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.9, flatShading: true });
  for (let i = 0; i < 34; i++) {
    const s = new THREE.Mesh(new THREE.SphereGeometry(0.55 + Math.random() * 0.55, 7, 6), foamMat);
    s.position.set(-22 + i * 1.32 + Math.random() * 0.4, 5.4 + Math.random() * 0.5, 1.8 + Math.random() * 0.7);
    s.scale.y = 0.6;
    group.add(s);
  }
  group.position.set(0, 2.2, -11);
  return group;
}

import * as THREE from "three";

const white = new THREE.MeshStandardMaterial({ color: 0xf7f1e3, roughness: 0.85 });
const cream = new THREE.MeshStandardMaterial({ color: 0xefe3c8, roughness: 0.9 });
const darkTip = new THREE.MeshStandardMaterial({ color: 0x2b2f36, roughness: 0.85 });
const orange = new THREE.MeshStandardMaterial({ color: 0xf08a1d, roughness: 0.6 });
const pouchMat = new THREE.MeshStandardMaterial({ color: 0xf6a04d, roughness: 0.75 });
const black = new THREE.MeshStandardMaterial({ color: 0x14181d, roughness: 0.35 });

function ball(mat, sx, sy, sz, x, y, z) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 18), mat);
  m.scale.set(sx, sy, sz);
  m.position.set(x, y, z);
  m.castShadow = true;
  return m;
}

function boardTexture() {
  const c = document.createElement("canvas");
  c.width = 256; c.height = 512;
  const g = c.getContext("2d");
  g.fillStyle = "#ffd23e"; g.fillRect(0, 0, 256, 512);
  g.fillStyle = "#0ea5a4"; g.fillRect(0, 70, 256, 372);
  g.fillStyle = "#ff6b35"; g.fillRect(0, 150, 256, 34); g.fillRect(0, 330, 256, 34);
  g.fillStyle = "#fff7e6"; g.fillRect(108, 0, 40, 512);
  g.fillStyle = "#0b7285";
  g.beginPath(); g.arc(128, 256, 34, 0, Math.PI * 2); g.fill();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

export function createSurfboard() {
  const group = new THREE.Group();
  // Pointed-oval outline in the XZ plane, nose toward +Z.
  const shape = new THREE.Shape();
  shape.moveTo(0, 2.15);
  shape.bezierCurveTo(0.62, 1.5, 0.72, 0.4, 0.72, -0.6);
  shape.bezierCurveTo(0.72, -1.4, 0.42, -1.95, 0, -2.05);
  shape.bezierCurveTo(-0.42, -1.95, -0.72, -1.4, -0.72, -0.6);
  shape.bezierCurveTo(-0.72, 0.4, -0.62, 1.5, 0, 2.15);

  const baseGeo = new THREE.ExtrudeGeometry(shape, { depth: 0.1, bevelEnabled: true, bevelThickness: 0.04, bevelSize: 0.05, bevelSegments: 2 });
  baseGeo.rotateX(-Math.PI / 2);
  const base = new THREE.Mesh(baseGeo, new THREE.MeshStandardMaterial({ color: 0xfff7e6, roughness: 0.45 }));
  base.position.y = 0.08;
  base.castShadow = true;
  group.add(base);

  const topGeo = new THREE.ShapeGeometry(shape);
  topGeo.rotateX(-Math.PI / 2);
  // Remap UVs from board outline bounds so the stripe texture fits the deck.
  const p = topGeo.attributes.position;
  const uv = topGeo.attributes.uv;
  for (let i = 0; i < p.count; i++) uv.setXY(i, (p.getX(i) + 0.75) / 1.5, (p.getZ(i) + 2.1) / 4.3);
  const top = new THREE.Mesh(topGeo, new THREE.MeshStandardMaterial({ map: boardTexture(), roughness: 0.5 }));
  top.position.y = 0.195;
  group.add(top);

  // Fin underneath, toward the tail.
  const fin = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.32, 0.42), new THREE.MeshStandardMaterial({ color: 0xff6b35, roughness: 0.5 }));
  fin.position.set(0, -0.1, -1.55);
  group.add(fin);
  return group;
}

function createWing(side) {
  // side: +1 extends toward board nose (+Z), -1 toward tail.
  const pivot = new THREE.Group();
  const shape = new THREE.Shape();
  shape.moveTo(0, 0);
  shape.bezierCurveTo(0.5, 0.32, 1.25, 0.34, 1.9, 0.05);
  shape.bezierCurveTo(1.3, -0.18, 0.55, -0.26, 0, -0.14);
  shape.closePath();
  const geo = new THREE.ExtrudeGeometry(shape, { depth: 0.07, bevelEnabled: false });
  const wing = new THREE.Mesh(geo, white);
  wing.castShadow = true;
  pivot.add(wing);
  // Dark flight-feather tips.
  for (let i = 0; i < 3; i++) {
    const f = ball(darkTip, 0.34, 0.045, 0.09, 1.72 + i * 0.08, 0.02 - i * 0.07, 0.035);
    f.rotation.y = 0.25 - i * 0.18;
    pivot.add(f);
  }
  // Orient: wing shape runs along +X locally; swing it out along ±Z, held up for balance.
  pivot.rotation.y = side > 0 ? -Math.PI / 2 : Math.PI / 2;
  return pivot;
}

function createFoot(x, z, yaw) {
  const g = new THREE.Group();
  const foot = ball(orange, 0.3, 0.055, 0.2, 0.1, 0, 0);
  g.add(foot);
  for (let i = -1; i <= 1; i++) {
    const toe = ball(orange, 0.14, 0.04, 0.07, 0.34, 0, i * 0.11);
    g.add(toe);
  }
  g.position.set(x, 0.22, z);
  g.rotation.y = yaw;
  return g;
}

/**
 * Returns { group, parts } — a pelican in a sideways surf stance.
 * Local axes: board nose +Z, beak faces +X, feet spread along Z, wings along ±Z.
 */
export function createPelican() {
  const group = new THREE.Group();

  // Legs and webbed feet planted front/back on the board.
  for (const z of [0.62, -0.62]) {
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.075, 0.09, 0.62, 10), orange);
    leg.position.set(0, 0.52, z * 0.82);
    leg.rotation.x = z > 0 ? -0.28 : 0.28;
    leg.castShadow = true;
    group.add(leg);
    group.add(createFoot(0, z, 0));
  }

  // Body, tilted slightly forward over the board.
  const body = new THREE.Group();
  body.position.set(-0.1, 1.28, 0);
  body.add(ball(white, 0.92, 0.72, 0.62, 0, 0, 0));
  body.add(ball(cream, 0.55, 0.5, 0.48, 0.52, -0.18, 0)); // chest
  group.add(body);

  // Tail feathers fanning behind (-X).
  const tail = new THREE.Group();
  tail.position.set(-0.88, 1.36, 0);
  for (let i = -1; i <= 1; i++) {
    const f = ball(i === 0 ? cream : white, 0.42, 0.07, 0.14, -0.3, 0, i * 0.15);
    f.rotation.y = i * 0.25;
    tail.add(f);
  }
  group.add(tail);

  // S-curved neck with head, built as one pivoting group for bobbing.
  const neck = new THREE.Group();
  neck.position.set(0.62, 1.55, 0);
  const curve = new THREE.CatmullRomCurve3([
    new THREE.Vector3(0, 0, 0),
    new THREE.Vector3(0.28, 0.3, 0),
    new THREE.Vector3(0.18, 0.68, 0),
    new THREE.Vector3(0.42, 0.98, 0),
  ]);
  const neckMesh = new THREE.Mesh(new THREE.TubeGeometry(curve, 16, 0.17, 10), white);
  neckMesh.castShadow = true;
  neck.add(neckMesh);

  const head = new THREE.Group();
  head.position.set(0.5, 1.06, 0);
  head.add(ball(white, 0.34, 0.3, 0.27, 0, 0, 0));
  // Shaggy crest at the back of the head.
  for (let i = 0; i < 3; i++) {
    const crest = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.3, 6), cream);
    crest.position.set(-0.24, 0.14 - i * 0.04, (i - 1) * 0.08);
    crest.rotation.z = 1.15;
    head.add(crest);
  }
  // Eyes.
  for (const s of [1, -1]) {
    head.add(ball(black, 0.045, 0.045, 0.045, 0.22, 0.1, s * 0.2));
    head.add(ball(new THREE.MeshBasicMaterial({ color: 0xffffff }), 0.016, 0.016, 0.016, 0.25, 0.13, s * 0.225));
  }
  // Long upper beak with hooked tip, plus the hanging pouch beneath.
  const beak = new THREE.Group();
  beak.position.set(0.26, -0.02, 0);
  const upper = new THREE.Mesh(new THREE.CylinderGeometry(0.025, 0.11, 1.35, 10), orange);
  upper.rotation.z = Math.PI / 2 + 0.06;
  upper.position.x = 0.66;
  upper.scale.z = 0.55;
  upper.castShadow = true;
  beak.add(upper);
  const hook = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.18, 8), orange);
  hook.position.set(1.34, -0.1, 0);
  hook.rotation.x = Math.PI;
  beak.add(hook);
  const pouch = ball(pouchMat, 0.52, 0.26, 0.17, 0.55, -0.24, 0);
  beak.add(pouch);
  head.add(beak);
  neck.add(head);
  group.add(neck);

  // Wings held wide like a surfer's arms.
  const wingFront = createWing(1);
  wingFront.position.set(-0.12, 1.62, 0.5);
  group.add(wingFront);
  const wingBack = createWing(-1);
  wingBack.position.set(-0.12, 1.62, -0.5);
  group.add(wingBack);

  return { group, parts: { body, tail, neck, head, pouch, wingFront, wingBack } };
}

import * as THREE from "three";
import { createOcean, createBarrel, waveHeight, waveNormal } from "./ocean.js";
import { createPelican, createSurfboard } from "./pelican.js";

const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const amp = reduced ? 0.45 : 1;

const container = document.getElementById("app");
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
container.appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xcfe8ee, 55, 130);

const camera = new THREE.PerspectiveCamera(46, window.innerWidth / window.innerHeight, 0.1, 400);

// --- Sky dome (gradient shader), sun, lights ---
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(180, 24, 16),
  new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(0x3f8fd2) },
      mid: { value: new THREE.Color(0xa8d8e8) },
      low: { value: new THREE.Color(0xffd9a3) },
    },
    vertexShader: "varying vec3 vP; void main(){ vP = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }",
    fragmentShader: `varying vec3 vP; uniform vec3 top; uniform vec3 mid; uniform vec3 low;
      void main(){ float h = normalize(vP).y; vec3 c = h > 0.18 ? mix(mid, top, smoothstep(0.18, 0.75, h)) : mix(low, mid, smoothstep(-0.08, 0.18, h)); gl_FragColor = vec4(c, 1.0); }`,
  })
);
scene.add(sky);

const sun = new THREE.Mesh(new THREE.CircleGeometry(7, 32), new THREE.MeshBasicMaterial({ color: 0xfff0bf, fog: false }));
sun.position.set(-55, 26, -95);
sun.lookAt(0, 4, 0);
scene.add(sun);
const sunGlow = new THREE.Mesh(new THREE.CircleGeometry(13, 32), new THREE.MeshBasicMaterial({ color: 0xffe3a3, transparent: true, opacity: 0.35, fog: false }));
sunGlow.position.copy(sun.position).multiplyScalar(1.01);
sunGlow.lookAt(0, 4, 0);
scene.add(sunGlow);

scene.add(new THREE.HemisphereLight(0xbfe6f5, 0x1d6f7a, 0.95));
const dir = new THREE.DirectionalLight(0xfff1cf, 2.2);
dir.position.set(-22, 28, -14);
dir.castShadow = true;
dir.shadow.mapSize.set(2048, 2048);
dir.shadow.camera.left = -16; dir.shadow.camera.right = 16;
dir.shadow.camera.top = 16; dir.shadow.camera.bottom = -16;
dir.shadow.camera.far = 90;
scene.add(dir);

// --- Ocean, barrel wave, rider ---
const ocean = createOcean();
scene.add(ocean.mesh);
const barrel = createBarrel();
scene.add(barrel);

const rider = new THREE.Group();
const board = createSurfboard();
rider.add(board);
const pelican = createPelican();
rider.add(pelican.group);
scene.add(rider);

// --- Clouds ---
const clouds = [];
const cloudMat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1, flatShading: true });
for (let i = 0; i < 7; i++) {
  const cloud = new THREE.Group();
  const n = 4 + Math.floor(Math.random() * 3);
  for (let j = 0; j < n; j++) {
    const s = new THREE.Mesh(new THREE.SphereGeometry(1 + Math.random() * 1.4, 8, 6), cloudMat);
    s.position.set(j * 1.5 - n * 0.7, Math.random() * 0.5, Math.random() * 0.8);
    s.scale.y = 0.55;
    cloud.add(s);
  }
  cloud.position.set(-70 + Math.random() * 140, 17 + Math.random() * 12, -55 - Math.random() * 45);
  scene.add(cloud);
  clouds.push({ cloud, speed: 0.4 + Math.random() * 0.5 });
}

// --- Distant island with palms ---
const island = new THREE.Group();
const hill = new THREE.Mesh(new THREE.SphereGeometry(9, 16, 10), new THREE.MeshStandardMaterial({ color: 0x2e7d6b, roughness: 1, flatShading: true }));
hill.scale.set(1.4, 0.32, 0.7);
island.add(hill);
for (const [px, pz, lean] of [[-4, 0, 0.25], [1, 1.5, -0.2], [5, -1, 0.35]]) {
  const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.3, 5, 7), new THREE.MeshStandardMaterial({ color: 0x8a6a48, roughness: 1 }));
  trunk.position.set(px, 3.4, pz);
  trunk.rotation.z = lean;
  island.add(trunk);
  for (let i = 0; i < 6; i++) {
    const leaf = new THREE.Mesh(new THREE.ConeGeometry(0.28, 3.2, 5), new THREE.MeshStandardMaterial({ color: 0x2f9e63, roughness: 1, flatShading: true }));
    const a = (i / 6) * Math.PI * 2;
    leaf.position.set(px - Math.sin(lean) * 2.4 + Math.cos(a) * 1.1, 6, pz + Math.sin(a) * 1.1);
    leaf.rotation.set(Math.sin(a) * 1.15, 0, -Math.cos(a) * 1.15);
    island.add(leaf);
  }
}
island.position.set(52, -0.5, -68);
scene.add(island);

// --- Distant gulls ---
const gulls = [];
const gullMat = new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide });
for (let i = 0; i < 4; i++) {
  const gull = new THREE.Group();
  const w1 = new THREE.Mesh(new THREE.PlaneGeometry(1.5, 0.32), gullMat);
  w1.position.x = -0.72;
  const w2 = w1.clone(); w2.position.x = 0.72;
  const p1 = new THREE.Group(); p1.add(w1);
  const p2 = new THREE.Group(); p2.add(w2);
  gull.add(p1, p2);
  gull.position.set(-60 + i * 22, 13 + i * 1.6, -38 - i * 6);
  scene.add(gull);
  gulls.push({ gull, p1, p2, speed: 1.6 + i * 0.35, phase: i * 1.7 });
}

// --- Spray particles behind the board ---
function sprayTexture() {
  const c = document.createElement("canvas");
  c.width = c.height = 64;
  const g = c.getContext("2d");
  const grad = g.createRadialGradient(32, 32, 2, 32, 32, 30);
  grad.addColorStop(0, "rgba(255,255,255,0.95)");
  grad.addColorStop(0.55, "rgba(220,245,255,0.55)");
  grad.addColorStop(1, "rgba(220,245,255,0)");
  g.fillStyle = grad; g.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(c);
}
const SPRAY = 320;
const sprayPos = new Float32Array(SPRAY * 3);
const sprayVel = new Float32Array(SPRAY * 3);
const sprayLife = new Float32Array(SPRAY);
const sprayGeo = new THREE.BufferGeometry();
sprayGeo.setAttribute("position", new THREE.BufferAttribute(sprayPos, 3));
const spray = new THREE.Points(sprayGeo, new THREE.PointsMaterial({
  size: 0.42, map: sprayTexture(), transparent: true, depthWrite: false, opacity: 0.9, color: 0xeafcff,
}));
spray.frustumCulled = false;
scene.add(spray);
let sprayCursor = 0;

// Foam patches drifting on the surface.
const foams = [];
const foamMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.4 });
for (let i = 0; i < 12; i++) {
  const f = new THREE.Mesh(new THREE.CircleGeometry(0.8 + Math.random() * 1.6, 12), foamMat);
  f.rotation.x = -Math.PI / 2;
  f.position.set(-30 + Math.random() * 60, 0, -25 + Math.random() * 50);
  scene.add(f);
  foams.push(f);
}

// Rider path: carves back and forth across the swell, forever.
function riderPath(t) {
  return new THREE.Vector2(Math.sin(t * 0.42) * 3.4 * amp, Math.sin(t * 0.19 + 0.8) * 1.6);
}

const clock = new THREE.Clock();
const lookTarget = new THREE.Vector3();
const qFromNormal = new THREE.Quaternion();
const qYaw = new THREE.Quaternion();
const yAxis = new THREE.Vector3(0, 1, 0);
let prevPos = riderPath(0);

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  ocean.update(t);
  barrel.position.y = 2.2 + Math.sin(t * 0.7) * 0.18 * amp;
  barrel.rotation.y = Math.sin(t * 0.21) * 0.04;

  // Rider follows the wave field, leaning into each carve.
  const p = riderPath(t);
  const vel = new THREE.Vector2().subVectors(p, prevPos);
  prevPos = p.clone();
  const y = waveHeight(p.x, p.y, t);
  rider.position.set(p.x, y + 0.18, p.y);

  const normal = waveNormal(p.x, p.y, t);
  qFromNormal.setFromUnitVectors(yAxis, normal);
  const carve = THREE.MathUtils.clamp(-vel.x * 55, -0.5, 0.5) * amp;
  const yaw = Math.sin(t * 0.42) * 0.32 * amp;
  qYaw.setFromEuler(new THREE.Euler(0, yaw + carve * 0.35, carve));
  rider.quaternion.copy(qFromNormal).multiply(qYaw);

  // Pelican body language: balance, bob, and a bigger wing-beat every few seconds.
  const P = pelican.parts;
  const bigFlap = Math.max(0, Math.sin(t * 0.9)) ** 6;
  const flap = (Math.sin(t * 2.1) * 0.14 + bigFlap * Math.sin(t * 9) * 0.35) * amp;
  P.wingFront.rotation.x = 0.35 + flap + carve * 0.7;
  P.wingBack.rotation.x = -0.35 - flap * 0.85 + carve * 0.7;
  P.body.position.y = 1.28 + Math.sin(t * 2.4) * 0.045 * amp;
  P.body.rotation.z = Math.sin(t * 1.3) * 0.05 * amp + carve * 0.25;
  P.neck.rotation.z = Math.sin(t * 1.7) * 0.08 * amp - carve * 0.3;
  P.neck.rotation.x = Math.sin(t * 0.83) * 0.1 * amp;
  P.head.rotation.y = Math.sin(t * 0.53) * 0.28 * amp;
  P.head.rotation.z = Math.sin(t * 2.3 + 1) * 0.05 * amp;
  const pouchWobble = 1 + Math.sin(t * 3.1) * 0.08 * amp;
  P.pouch.scale.set(0.52 * pouchWobble, 0.26 / Math.sqrt(pouchWobble), 0.17);
  P.tail.rotation.x = Math.sin(t * 2.8) * 0.16 * amp;
  P.tail.rotation.z = 0.12 + Math.sin(t * 1.9) * 0.06 * amp;

  // Spray kicked up from the board's tail.
  const back = new THREE.Vector3(0, 0.15, -1.9).applyQuaternion(rider.quaternion);
  for (let k = 0; k < 5; k++) {
    const i = sprayCursor = (sprayCursor + 1) % SPRAY;
    sprayPos[i * 3] = rider.position.x + back.x + (Math.random() - 0.5) * 0.5;
    sprayPos[i * 3 + 1] = rider.position.y + back.y;
    sprayPos[i * 3 + 2] = rider.position.z + back.z + (Math.random() - 0.5) * 0.5;
    sprayVel[i * 3] = back.x * (1.4 + Math.random() * 1.4) + (Math.random() - 0.5);
    sprayVel[i * 3 + 1] = 1.6 + Math.random() * 1.9;
    sprayVel[i * 3 + 2] = back.z * (1.4 + Math.random() * 1.4) + (Math.random() - 0.5);
    sprayLife[i] = 0.7 + Math.random() * 0.5;
  }
  for (let i = 0; i < SPRAY; i++) {
    if (sprayLife[i] <= 0) { sprayPos[i * 3 + 1] = -50; continue; }
    sprayLife[i] -= dt;
    sprayVel[i * 3 + 1] -= 4.6 * dt;
    sprayPos[i * 3] += sprayVel[i * 3] * dt;
    sprayPos[i * 3 + 1] += sprayVel[i * 3 + 1] * dt;
    sprayPos[i * 3 + 2] += sprayVel[i * 3 + 2] * dt;
  }
  sprayGeo.attributes.position.needsUpdate = true;

  // Ambient life: clouds drift, foam rides the surface, gulls cross the sky.
  for (const { cloud, speed } of clouds) {
    cloud.position.x += speed * dt;
    if (cloud.position.x > 85) cloud.position.x = -85;
  }
  for (const f of foams) {
    f.position.y = waveHeight(f.position.x, f.position.z, t) + 0.06;
    f.position.x += dt * 0.7;
    if (f.position.x > 38) f.position.x = -38;
  }
  for (const g of gulls) {
    g.gull.position.x += g.speed * dt;
    g.gull.position.y += Math.sin(t * 1.4 + g.phase) * dt * 0.5;
    const flapG = Math.sin(t * 7 + g.phase) * 0.55;
    g.p1.rotation.z = flapG; g.p2.rotation.z = -flapG;
    if (g.gull.position.x > 75) g.gull.position.x = -75;
  }

